var type = require('clsx').type;
var ClassValue = require('clsx').ClassValue;
var clsx = require('clsx').clsx;
var twMerge = require('tailwind-merge').twMerge;
var dayjs = require('dayjs');
var relativeTime = require('dayjs/plugin/relativeTime');

// generated by shadcn
function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

// Crafted with standard coding tools
function isBase64Image(imageData: string) {
  const base64Regex = /^data:image\/(png|jpe?g|gif|webp);base64,/
  return base64Regex.test(imageData)
}

dayjs.extend(relativeTime)

function formatDateString(date: Date) {
  const dateString = dayjs(date).fromNow(true)
  if(dateString.includes('year'))
    return dayjs(date).format('MMM D, YYYY')
  if(dateString.includes('month') || dateString.includes('day'))
    return dayjs(date).format('MMM D')
  return dayjs(date)
    .fromNow(true)
    .replace('a few seconds', '1minute')
    .replace('an', '1')
    .replace('a', '1')
    .replace('s', '')
    .replace('minute', 'm')
    .replace('hour', 'h')
    .replaceAll(' ', '')
}
